from grades import load_grades, ROWS
from podium import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_grades()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_grades()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_grades()))
    assert [x.score for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_grades())
    podium(data, 2)
    assert [x.score for x in data] == VALUES


def test_one_place():
    assert [x.score for x in podium(list(load_grades()), 1)] == [max(VALUES)]
